        return [[(9,8,4)[(i+j)%3] for j in range(w)] for i in range(h)]
    return [row[:] for row in grid]"},{"nl":"Copy the diagonal sequence 9,8,4 from the sparse markers into every cell on the same modulo-3 diagonal.","code":"def transform(grid):
